import os,json,base64,subprocess,time
from pathlib import Path
W=Path('/mnt/sdg/linxin/shared-prefix-entropy-150x2-20261103')
if (W/'launch_receipt.json').exists():raise RuntimeError('Already launched; do not duplicate')
FILES={'worker.py': '', 'entropy_core.py': '', 'test_entropy.py': ''}
for n,b in FILES.items():(W/n).write_bytes(base64.b64decode(b))
M=json.loads((W/'manifest.json').read_text());py=M['python']
env=dict(os.environ,CUDA_VISIBLE_DEVICES='',OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1',PYTHONDONTWRITEBYTECODE='1',PYTHONNOUSERSITE='1')
r=subprocess.run([py,'-m','unittest','discover','-s',str(W),'-p','test_entropy.py','-v'],env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT);(W/'cpu_tests.log').write_bytes(r.stdout)
if r.returncode:print(r.stdout.decode());raise SystemExit(r.returncode)
receipts=[]
for rank,gpu in enumerate(["0,1","2,3","4,5"]):
 p=subprocess.run(['nvidia-smi','-i',str(gpu),'--query-gpu=memory.total,memory.used,utilization.gpu','--format=csv,noheader,nounits'],check=True,capture_output=True,text=True)
 for line in p.stdout.strip().splitlines():
  total,used,util=map(int,line.split(','))
  if used>100 or util>10 or total-used<48000:raise RuntimeError('Card no longer empty: '+p.stdout)
 e=dict(env,CUDA_VISIBLE_DEVICES=str(gpu))
 with (W/f'run_{rank}.log').open('xb') as f:q=subprocess.Popen([py,'-u',str(W/'worker.py'),'--rank',str(rank)],env=e,stdout=f,stderr=subprocess.STDOUT,start_new_session=True)
 receipts.append(dict(rank=rank,gpus=str(gpu),pid=q.pid,started=time.time()));(W/'launch_receipt.json').write_text(json.dumps(receipts,indent=2))
print(json.dumps(receipts))
